<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0d0d12;
    font-family: system-ui, -apple-system, sans-serif;
    color: #e8e8ed;
    gap: 16px;
    user-select: none;
  }
  h1 {
    font-size: 1.1rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: #a0a0b8;
    text-transform: uppercase;
  }
  #sim {
    display: block;
    width: 480px;
    height: 480px;
    max-width: 92vw;
    max-height: 70vh;
    background: #16161f;
    border: 2px solid #2a2a3a;
    border-radius: 12px;
    cursor: crosshair;
    box-shadow: 0 8px 32px rgba(0,0,0,0.45), inset 0 0 60px rgba(0,0,0,0.3);
  }
  .controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    appearance: none;
    border: 1px solid #3a3a50;
    background: #1e1e2a;
    color: #e8e8ed;
    font-size: 0.9rem;
    font-weight: 500;
    padding: 10px 20px;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, transform 0.1s;
  }
  button:hover {
    background: #2a2a3e;
    border-color: #5a5a80;
  }
  button:active {
    transform: scale(0.96);
  }
  button#play.playing {
    background: #1a3a2a;
    border-color: #3a8a5a;
    color: #7dffa0;
  }
  .hint {
    font-size: 0.75rem;
    color: #606078;
  }
</style>
</head>
<body>
  <h1>Bouncing Balls</h1>
  <canvas id="sim" width="480" height="480"></canvas>
  <div class="controls">
    <button id="drop">Drop</button>
    <button id="play">Play</button>
    <button id="clear">Clear</button>
  </div>
  <p class="hint">Click canvas to add a ball</p>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 0.35;
  const RESTITUTION = 0.82;
  const FRICTION = 0.998;

  /** @type {{x:number,y:number,vx:number,vy:number,r:number,hue:number}[]} */
  let balls = [];
  let playing = false;
  let rafId = 0;

  const COLORS = [
    200, 170, 140, 30, 350, 280, 50, 320
  ];

  function randomHue() {
    return COLORS[Math.floor(Math.random() * COLORS.length)];
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    const radius = r != null ? r : 12 + Math.random() * 16;
    balls.push({
      x: x,
      y: y,
      vx: vx,
      vy: vy,
      r: radius,
      hue: randomHue()
    });
    draw();
  }

  function clearBalls() {
    balls = [];
    draw();
  }

  function step(dt = 1) {
    const n = Math.max(1, Math.round(dt));
    for (let s = 0; s < n; s++) {
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        b.vy += GRAVITY;
        b.vx *= FRICTION;
        b.x += b.vx;
        b.y += b.vy;

        // Left edge
        if (b.x - b.r < 0) {
          b.x = b.r;
          b.vx = Math.abs(b.vx) * RESTITUTION;
        }
        // Right edge
        if (b.x + b.r > W) {
          b.x = W - b.r;
          b.vx = -Math.abs(b.vx) * RESTITUTION;
        }
        // Top edge
        if (b.y - b.r < 0) {
          b.y = b.r;
          b.vy = Math.abs(b.vy) * RESTITUTION;
        }
        // Bottom edge
        if (b.y + b.r > H) {
          b.y = H - b.r;
          b.vy = -Math.abs(b.vy) * RESTITUTION;
        }

        // Clamp again to guarantee no escape / tunneling
        if (b.x - b.r < 0) b.x = b.r;
        if (b.x + b.r > W) b.x = W - b.r;
        if (b.y - b.r < 0) b.y = b.r;
        if (b.y + b.r > H) b.y = H - b.r;
      }
    }
    draw();
  }

  function draw() {
    ctx.fillStyle = '#16161f';
    ctx.fillRect(0, 0, W, H);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let g = 40; g < W; g += 40) {
      ctx.beginPath(); ctx.moveTo(g, 0); ctx.lineTo(g, H); ctx.stroke();
    }
    for (let g = 40; g < H; g += 40) {
      ctx.beginPath(); ctx.moveTo(0, g); ctx.lineTo(W, g); ctx.stroke();
    }

    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, `hsl(${b.hue}, 85%, 72%)`);
      grad.addColorStop(0.55, `hsl(${b.hue}, 75%, 55%)`);
      grad.addColorStop(1, `hsl(${b.hue}, 70%, 38%)`);

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // highlight
      ctx.beginPath();
      ctx.ellipse(
        b.x - b.r * 0.28, b.y - b.r * 0.32,
        b.r * 0.28, b.r * 0.18,
        -0.4, 0, Math.PI * 2
      );
      ctx.fillStyle = 'rgba(255,255,255,0.28)';
      ctx.fill();
    }
  }

  function loop() {
    if (!playing) return;
    step(1);
    rafId = requestAnimationFrame(loop);
  }

  function setPlaying(on) {
    playing = on;
    const btn = document.getElementById('play');
    if (playing) {
      btn.textContent = 'Pause';
      btn.classList.add('playing');
      cancelAnimationFrame(rafId);
      rafId = requestAnimationFrame(loop);
    } else {
      btn.textContent = 'Play';
      btn.classList.remove('playing');
      cancelAnimationFrame(rafId);
    }
  }

  // UI
  document.getElementById('drop').addEventListener('click', () => {
    const r = 12 + Math.random() * 16;
    const x = r + Math.random() * (W - 2 * r);
    const y = r + Math.random() * 80;
    const vx = (Math.random() - 0.5) * 6;
    addBall(x, y, vx, 0, r);
  });

  document.getElementById('play').addEventListener('click', () => {
    setPlaying(!playing);
  });

  document.getElementById('clear').addEventListener('click', () => {
    clearBalls();
  });

  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    const r = 12 + Math.random() * 16;
    const vx = (Math.random() - 0.5) * 4;
    addBall(x, y, vx, 0, r);
  });

  // Programmatic API
  window.sim = {
    get w() { return W; },
    get h() { return H; },
    balls() {
      return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
    },
    addBall(x, y, vx = 0, vy = 0, r) {
      addBall(x, y, vx, vy, r);
    },
    clear() {
      clearBalls();
    },
    step(dt = 1) {
      step(dt);
    }
  };

  draw();
})();
</script>
</body>
</html>
